  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        raise ValueError('Empty node set')
    edges = []
    for a, b, d in distances:
        mr = max(core_distance[a], core_distance[b], d)
        if a > b:
            a, b = b, a
        edges.append((mr, a, b))
    edges.sort()
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for weight, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is not connected; cannot form MST')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
